def test_build_request_maps_parameters():
    request = cloudrc_resource_info.build_request(FakeModels, {}, None, 100)
    assert request.MaxResults == 100
    # The cursor stays off the first request; it is only set once a page returns one.
    assert not hasattr(request, "NextToken")


def test_build_request_sorts_filters():
    request = cloudrc_resource_info.build_request(FakeModels, {"b-name": ["v1"], "a-name": ["v2"]}, None, 100)
    assert [(item.Key, item.Values) for item in request.Filters] == [
        ("a-name", ["v2"]), ("b-name", ["v1"]),
    ]


def test_run_module_follows_the_cursor_to_the_last_page(monkeypatch):
    client = FakeClient([
        FakeResponse([FakeItem("a"), FakeItem("b")], 3, "cursor-2", False),
        FakeResponse([FakeItem("c")], 3, "", True),
    ])
    fake = _run(monkeypatch, client, region="ap-guangzhou", filters={}, page_size=100)
    payload = fake.exit_payload
    assert payload["changed"] is False
    assert [item["Marker"] for item in payload["resources"]] == ["a", "b", "c"]
    assert payload["total_count"] == 3
    assert payload["request_id"] == "req-token"
    assert [getattr(request, "NextToken", None)
            for request in client.requests] == [None, "cursor-2"]


